mapper.select:
SELECT * FROM ( SELECT ( SELECT max(pp.project_number) FROM prj_project_lease_item ppli, prj_project pp WHERE ppli.lease_item_id = hli.lease_item_id AND ppli.project_id = pp.project_id AND pp.data_class = 'NORMAL' ) project_number, ( SELECT max(pp.contract_number) FROM prj_project_lease_item ppli, prj_project pp WHERE ppli.lease_item_id = hli.lease_item_id AND ppli.project_id = pp.project_id AND pp.data_class = 'VIRTUAL_CON' ) contract_number, ( SELECT pp.contract_status FROM prj_project_lease_item ppli, prj_project pp WHERE ppli.lease_item_id = hli.lease_item_id AND ppli.project_id = pp.project_id AND pp.data_class = 'VIRTUAL_CON' and rownum=1 ) AS contract_status, ( SELECT hbt.description FROM hls_business_type hbt WHERE hbt.document_category = 'REGULATORY_ASSET_CLASS' AND hbt.business_type = hli.asset_types ) asset_types_n, ( SELECT scv.MEANING FROM sys_code_b sc, sys_code_value_b scv WHERE sc.CODE_ID = scv.CODE_ID AND sc. CODE = 'SYS.YES_NO' AND scv. VALUE = hli.if_since_the_mortgage ) if_since_the_mortgage_n, ( SELECT hdt.description FROM hls_document_type hdt WHERE hdt.document_category = 'REGULATORY_ASSET_CLASS' AND hdt.business_type = hli.asset_types AND hdt.document_type = hli.asset_types_sub ) asset_types_sub_n, ( SELECT nvl( sum(hlil.QUANTITY * hlil.PRICE), 0 ) FROM hls_lease_item_list hlil WHERE hlil.lease_item_id = hli.lease_item_id ) net_asset_value_total, ( SELECT hbm.bp_name FROM hls_bp_master hbm WHERE hbm.bp_id = hli.vender_id ) vender_id_n, hli.creation_date lease_create_date, ( SELECT FC.CURRENCY_NAME FROM FND_CURRENCY FC WHERE FC.ENABLED_FLAG = 'Y' AND FC.CURRENCY_CODE = hli.CURRENCY ) currency_n, ( SELECT fe. NAME FROM fnd_employee fe WHERE fe.employee_id = hli.owner_user_id ) AS owner_user_name, ( SELECT scvb.MEANING value_name FROM sys_code_b scb, sys_code_value_b scvb WHERE scb.CODE_ID = scvb.CODE_ID AND scb. CODE = 'ASSET_STATUS' AND scvb. VALUE = hli.ASSET_STATUS ) asset_status_n, ( SELECT wm_concat(DISTINCT b.bp_name) FROM prj_project_bp pp, prj_project_lease_item pi, hls_bp_master b WHERE pp.project_id = pi.project_id AND pp.BP_TYPE = 'TENANT' AND pp.BP_CATEGROY = 'CON_CONTRACT' AND pp.bp_id = b.bp_id AND pi.lease_item_id = hli.lease_item_id ) bp_name, hli.*, hli.CREATED_BY document_created_by FROM hls_lease_item hli WHERE hli.LEASE_ITEM_TYPE = 'LEASE' AND hli.enabled_flag = 'Y' ) v
1=1
and (v.document_created_by = #{request.userId} or #{request.employeeCode} in('ADMIN','HULITING','CHENGUANGFU','WANGPEI') OR exists( select 1 from fnd_org_unit a1,fnd_employee a2,fnd_employee_assigns a3,FND_ORG_POSITION a4 where a3.employee_id=a2.employee_id and a3.unit_id=a1.unit_id and a4.position_id=a3.position_id and a4.chief_position_flag='Y' and employee_code=#{request.employeeCode} AND A1.UNIT_ID IN(select b.unit_id from sys_user_allocation a,fnd_employee_assigns b where a.user_id=v.document_created_by AND a.employee_assign_id=b.employee_assign_id)))
and v.lease_item_id = #{leaseItemId}
and v.lease_item_code like #{leaseItemCode}
and v.bp_name like #{bpName}
and v.full_name like #{fullName}
and v.asset_types = #{assetTypes}
and v.if_since_the_mortgage = #{ifSinceTheMortgage}
and v.net_asset_value_total = #{netAssetValueTotal}
ORDER BY v.creation_date DESC

SELECT * FROM ( SELECT ppli.project_number, ppli_cc.contract_number, ppli_cc.contract_status, hbt.description asset_types_n, ( SELECT scv.MEANING FROM sys_code_b sc, sys_code_value_b scv WHERE sc.CODE_ID = scv.CODE_ID AND sc.CODE = 'SYS.YES_NO' AND scv. VALUE = hli.if_since_the_mortgage ) AS if_since_the_mortgage_n, hdt.description AS asset_types_sub_n, hlil_total.net_asset_value_total, ( SELECT hbm.bp_name FROM hls_bp_master hbm WHERE hbm.bp_id = hli.vender_id ) AS vender_id_n, hli.creation_date AS lease_create_date, ( SELECT FC.CURRENCY_NAME FROM FND_CURRENCY FC WHERE FC.ENABLED_FLAG = 'Y' AND FC.CURRENCY_CODE = hli.CURRENCY ) AS currency_n, ( SELECT fe.NAME FROM fnd_employee fe WHERE fe.employee_id = hli.owner_user_id ) AS owner_user_name, ( SELECT scvb.MEANING AS value_name FROM sys_code_b scb, sys_code_value_b scvb WHERE scb.CODE_ID = scvb.CODE_ID AND scb.CODE = 'ASSET_STATUS' AND scvb. VALUE = hli.ASSET_STATUS ) AS asset_status_n, ppli_bp.bp_name, ( SELECT meaning FROM sys_code_value_b_v WHERE CODE = 'PLEDGE_STATE0' AND code_value = hli.PLEDGE_STATE ) PLEDGE_STATE_N, hli.CREATION_DATE, hli.LEASE_ITEM_ID, hli.LEASE_ITEM_CODE, hli.ASSET_TYPES, hli.IF_SINCE_THE_MORTGAGE, hli.FULL_NAME, hli.BRAND, hli.MORTGAGE_DATE_FROM, hli.MORTGAGE_DATE_TO, hlil.asset_name, hlil.PRICE, hlil.QUANTITY, hlil.SPECIFICATION, hlil.MANUFACTURER, hlil.ASSET_NUM, hlil.INVOICE_NUM, hlil.IMG_NUM, hlil.INSTALLATION_SITE, hlil.DESCRIPTION, hli.CREATED_BY AS document_created_by FROM hls_lease_item hli LEFT JOIN ( SELECT ppli.lease_item_id, MAX( pp.project_number ) AS project_number FROM prj_project_lease_item ppli, prj_project pp WHERE ppli.project_id = pp.project_id AND pp.data_class = 'NORMAL' GROUP BY ppli.lease_item_id ) ppli ON ppli.lease_item_id = hli.lease_item_id LEFT JOIN ( SELECT ppli.lease_item_id, MAX( pp.contract_number ) AS contract_number, contract_status FROM prj_project_lease_item ppli, prj_project pp WHERE ppli.project_id = pp.project_id AND pp.data_class = 'VIRTUAL_CON' GROUP BY ppli.lease_item_id ) ppli_cc ON ppli_cc.lease_item_id = hli.lease_item_id LEFT JOIN hls_business_type hbt ON hbt.document_category = 'ASSET_TYPES' AND hbt.business_type = hli.asset_types LEFT JOIN hls_document_type hdt ON hdt.document_category = 'ASSET_TYPES' AND hdt.business_type = hli.asset_types AND hdt.document_type = hli.asset_types_sub LEFT JOIN ( SELECT hlil.lease_item_id, nvl( SUM( hlil.QUANTITY * hlil.PRICE ), 0 ) AS net_asset_value_total FROM hls_lease_item_list hlil GROUP BY hlil.lease_item_id ) AS hlil_total ON hlil_total.lease_item_id = hli.lease_item_id LEFT JOIN ( SELECT pi.lease_item_id, wm_concat( DISTINCT b.bp_name ) AS bp_name FROM prj_project_bp pp, prj_project_lease_item pi, hls_bp_master b WHERE pp.project_id = pi.project_id AND pp.BP_TYPE = 'TENANT' AND pp.BP_CATEGROY = 'CON_CONTRACT' AND pp.bp_id = b.bp_id GROUP BY pi.lease_item_id ) ppli_bp ON ppli_bp.lease_item_id = hli.lease_item_id, hls_lease_item_list hlil WHERE hli.LEASE_ITEM_TYPE = 'LEASE' AND hli.enabled_flag = 'Y' AND hlil.lease_item_id = hli.lease_item_id ) v
1=1
and v.lease_item_id = #{leaseItemId}
and v.lease_item_code like concat(concat('%',#{leaseItemCode}),'%')
and v.pledge_state_n like concat(concat('%',#{pledgeStateN}),'%')
and v.asset_name like concat(concat('%',#{assetName}),'%')
and v.bp_name like #{bpName}
and v.full_name like #{fullName}
and v.asset_types = #{assetTypes}
and v.if_since_the_mortgage = #{ifSinceTheMortgage}
and v.net_asset_value_total = #{netAssetValueTotal}
ORDER BY v.creation_date DESC

select * from (select t.LEASE_ITEM_ID, t.LEASE_ITEM_CODE, t.full_name, t.ASSESSMENT_TYPE, t.PATTERN, ( SELECT meaning FROM sys_code_value_b_v WHERE CODE = 'HLS.PATTERN' AND code_value = t.PATTERN ) PATTERN_N, t.MORTGAGOR, ( SELECT hbm.bp_name FROM hls_bp_master hbm WHERE hbm.bp_id = t.MORTGAGOR ) MORTGAGOR_N, ( select sum(a.evaluation_value) from ((select t1.evaluation_value,t2.lease_item_id from hls_lease_item_detail t1,hls_lease_item t2 where t1.PATTERN_DET = 'MOVABLE_PROPERTY_PLEDGE' and t1.lease_item_id = t2.lease_item_id ) union (select t1.evaluation_value,t2.lease_item_id from hls_lease_item_detail t1,hls_lease_item t2 where t1.PATTERN_DET = 'NO_MOVABLE_PROPERTY_PLEDGE' and t1.lease_item_id = t2.lease_item_id )) a where a.lease_item_id = t.lease_item_id ) ASSET_VALUE_TOTAL, ( select sum(pled.evaluation_value) from ( select t1.evaluation_value,t1.lease_item_id from hls_lease_item_detail t1,hls_lease_item t2 where t1.PATTERN_DET = 'DZ_PROPERTY_PLEDGE' and t1.lease_item_id = t2.lease_item_id) pled where pled.lease_item_id = t.lease_item_id ) PLEDGE_VALUE_TOTAL, t.PLEDGE_STATE, ( SELECT meaning FROM sys_code_value_b_v WHERE CODE = 'PLEDGE_STATE0' AND code_value = t.PLEDGE_STATE ) PLEDGE_STATE_N, ( SELECT wm_concat(p.project_number) FROM prj_project_chance_mp pi, prj_project p WHERE pi.project_id = p.project_id AND pi.lease_item_id = t.lease_item_id and p.data_class = 'NORMAL' ) AS project_number, ( SELECT wm_concat(p.contract_number) FROM prj_project_chance_mp pi, prj_project p WHERE pi.project_id = p.project_id AND pi.lease_item_id = t.lease_item_id AND p.data_class = 'VIRTUAL_CON' ) AS contract_number, t.IF_SINCE_THE_MORTGAGE, (select meaning from sys_code_value_b_v where code = 'SYS.YES_NO' and code_value = t.IF_SINCE_THE_MORTGAGE) IF_SINCE_THE_MORTGAGE_N, t.created_by document_created_by, (SELECT fe. NAME FROM fnd_employee fe WHERE fe.employee_id = t.owner_user_id ) AS owner_user_name,
nvl ( ( SELECT dbms_lob.substr(wm_concat ( p.contract_status ), 1000 ) FROM prj_project_chance_mp pi, prj_project p WHERE pi.project_id = p.project_id AND pi.lease_item_id = t.lease_item_id AND p.data_class = 'VIRTUAL_CON' ), 'NEW' ) AS contract_status FROM hls_lease_item t where t.enabled_flag = 'Y' and t.LEASE_ITEM_TYPE in ('MORTGAGE','PLEDGE') )v
v.contract_status != 'SIGN'
and (v.document_created_by = #{createdBy} or #{request.employeeCode} in('ADMIN') OR exists( select 1 from fnd_org_unit a1,fnd_employee a2,fnd_employee_assigns a3,FND_ORG_POSITION a4 where a3.employee_id=a2.employee_id and a3.unit_id=a1.unit_id and a4.position_id=a3.position_id and a4.chief_position_flag='Y' and employee_code=#{request.employeeCode} AND A1.UNIT_ID IN(select b.unit_id from sys_user_allocation a,fnd_employee_assigns b where a.user_id=v.document_created_by AND a.employee_assign_id=b.employee_assign_id)))
and v.lease_item_id = #{leaseItemId}
and v.lease_item_code like concat(concat('%',#{leaseItemCode}),'%')
and v.full_name like concat(concat('%',#{fullName}),'%')
and v.lease_item_type = #{leaseItemType}
and v.pattern = #{pattern}
and v.MORTGAGOR_N like concat(concat('%',#{mortgagorN}),'%')
and v.ASSET_VALUE_TOTAL = #{assetValueTotal}
and v.PLEDGE_VALUE_TOTAL = #{pledgeValueTotal}
order by v.lease_item_id desc

select hli.lease_item_id, hli.full_name, hli.LEASE_ITEM_TYPE, hli.lease_item_code, (select meaning from sys_code_value_b_v where code = 'HLS.COLLATERAL_TYPE' and code_value = hli.LEASE_ITEM_TYPE) LEASE_ITEM_TYPE_N, (select a.MORTGAGE_PLEDGE_AMOUNT from (select hlid.lease_item_id, sum(hlid.MORTGAGE_PLEDGE_AMOUNT) as MORTGAGE_PLEDGE_AMOUNT from hls_lease_item_detail hlid group by hlid.lease_item_id) a where a.lease_item_id = hli.lease_item_id) MORTGAGE_AMOUNT_TOTAL, (select a.EVALUATION_VALUE from (select hlid.lease_item_id, sum(hlid.EVALUATION_VALUE) as EVALUATION_VALUE from hls_lease_item_detail hlid group by hlid.lease_item_id) a where a.lease_item_id = hli.lease_item_id) ASSET_VALUE_TOTAL, hli.PATTERN, (select meaning from sys_code_value_b_v where code ='HLS.PATTERN' and code_value = hli.PATTERN) PATTERN_N, hli.REGULATORY_ASSET_CLASS, (select t.description from hls_business_type t where t.document_category = 'REGULATORY_ASSET_CLASS' and t.business_type = hli.REGULATORY_ASSET_CLASS) REGULATORY_ASSET_CLASS_N, hli.REGULATORY_ASSET_CLASS_SUB, (select t.description from hls_document_type t where t.document_category = 'REGULATORY_ASSET_CLASS' and t.business_type = hli.REGULATORY_ASSET_CLASS and t.document_type = hli.REGULATORY_ASSET_CLASS_SUB) REGULATORY_ASSET_CLASS_SUB_N, hli.collateral_categories, (select t.description from hls_collateral_categories t where t.collateral_categories = hli.collateral_categories) collateral_categories_N, hli.collateral_classify_one, (select t.description from hls_collateral_classify_one t where t.collateral_classify_one = hli.collateral_classify_one) collateral_classify_one_N, hli.collateral_classify_two, (select t.description from hls_collateral_classify_two t where t.collateral_classify_two = hli.collateral_classify_two) collateral_classify_two_N, hli.MORTGAGOR, (select hbm.bp_name from hls_bp_master hbm where hbm.bp_id = hli.MORTGAGOR) MORTGAGOR_N, hli.MORTGAGE_SEQUENCE, (select meaning from sys_code_value_b_v where code = 'HLS.MORTGAGE_SEQUENCE' and code_value = hli.MORTGAGE_SEQUENCE) MORTGAGE_SEQUENCE_N, hli.VALUATION_METHOD, (select meaning from sys_code_value_b_v where code = 'HLS.VALUATION_METHOD' and code_value = hli.VALUATION_METHOD) VALUATION_METHOD_N, hli.bond_amount, hli.MORTGAGE_DATE_FROM, hli.mortgage_date_to, hli.MORTGAGE_AMOUNT, hli.CURRENCY, (SELECT FC.CURRENCY_NAME FROM FND_CURRENCY FC WHERE FC.ENABLED_FLAG = 'Y' and FC.CURRENCY_CODE = hli.CURRENCY) CURRENCY_N, hli.ASSET_VALUE, hli.VALUATION_DATE, hli.VALUATION_UNIT, hli.USAGE_TYPE, (select meaning from sys_code_value_b_v where code = 'HLS.USAGE_TYPE' and code_value = hli.USAGE_TYPE) USAGE_TYPE_N, hli.BUILDING_AREA, hli.EQUITY_NUMBER, hli.FLOOR_AREA, hli.IF_SINCE_THE_MORTGAGE, (select meaning from sys_code_value_b_v where code = 'SYS.YES_NO' and code_value = hli.IF_SINCE_THE_MORTGAGE) IF_SINCE_THE_MORTGAGE_N, hli.LAND_LOCATED, hli.PLEDGE_STATE , hli.LAND_USE, (select meaning from sys_code_value_b_v where code = 'PLEDGE_STATE0' and code_value = hli.PLEDGE_STATE) PLEDGE_STATE_N, ( select hr.result_id from hls_web_excel_calc_result hr where hr.source_document_id = hli.lease_item_id and hr.source_document_category = 'MORTGAGE_PLEDGE_REPORT') result_id, ( select h.excel_id from hls_web_excel h where h.enabled_flag = 'Y' and h.excel_type = 'MORTGAGE_PLEDGE_REPORT') excel_id from hls_lease_item hli
(hli.LEASE_ITEM_TYPE in ('MORTGAGE','PLEDGE') or hli.if_since_the_mortgage = 'Y')
and hli.lease_item_id = #{leaseItemId}
